#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353LL;

long long power(long long x, long long y, long long p) {
    long long res = 1LL;
    x %= p;
    while (y > 0) {
        if (y & 1)
            res = (res * x) % p;
        y >>= 1;
        x = (x * x) % p;
    }
    return res;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    long long N, M, L, R;
    cin >> N >> M >> L >> R;
    long long temp = N * M;
    long long exp = temp;
    long long base = R - L + 1;
    long long res = power(base, exp, MOD);
    if ((N * M) % 2 == 0) {
        if ((R - L) % 2 == 0)
            res = (res + 1) % MOD;
        res = (res * power(2, MOD - 2, MOD)) % MOD;
    }
    cout << res << "\n";
    return 0;
}

